int parse_csv_line(const char *line, char fields[][MAX_FIELD_LEN], int max_fields) {
    int num_fields = 0;
    char *token;
    char *str = strdup(line);
    token = strtok(str, ",");

    while (token!= NULL && num_fields < max_fields) {
        strncpy(fields[num_fields], token, MAX_FIELD_LEN);
        fields[num_fields][MAX_FIELD_LEN - 1] = '\0';
        token = strtok(NULL, ",");
        num_fields++;
    }

    free(str);
    return num_fields;
}
